import { layoutWinFlights } from '../app/win-flight-layout.js';

const active = new WeakMap();
export function clearWinFlights(quad) { active.get(quad)?.(); }

/** Visual only: the existing receipt and individual accessible prizes remain authoritative. */
export function launchWinFlights(quad, center) {
  clearWinFlights(quad);
  const view = quad.ownerDocument.defaultView;
  if (view.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  const bounds = quad.getBoundingClientRect();
  const width = quad.clientWidth, height = quad.clientHeight;
  if (!width || !height || !bounds.width || !bounds.height) return;
  const sx = width / bounds.width, sy = height / bounds.height;
  const local = node => {
    const r = node.getBoundingClientRect();
    return { left: (r.left - bounds.left) * sx, top: (r.top - bounds.top) * sy, width: r.width * sx, height: r.height * sy };
  };
  const obstacles = [center, quad.querySelector('.replay-win-description'), quad.querySelector('.replay-badge-overflow-label')]
    .filter(Boolean).map(local);
  const entries = [...quad.querySelectorAll('.replay-badge-wrap')].flatMap(badge => {
    const reward = badge.querySelector('.replay-badge-reward-pop');
    if (!reward) return [];
    const label = reward.cloneNode(true);
    label.className = 'replay-win-flight';
    label.style.maxWidth = `${width - 6}px`;
    const r = local(badge);
    return [{ badge, label, x: r.left + r.width / 2, y: r.top + r.height / 2 }];
  });
  // Mount every label before measuring any of them. Alternating append/read
  // forced a full layout for each prize on dense winning quadrants.
  for (const { label } of entries) quad.appendChild(label);
  for (const entry of entries) {
    entry.width = entry.label.offsetWidth;
    entry.height = entry.label.offsetHeight;
  }
  const positions = layoutWinFlights(entries, { left: 3, right: width - 3, top: 3, bottom: height - 3 }, obstacles);
  let lastDelay = 0;
  entries.forEach((entry, index) => {
    const p = positions[index];
    if (!p) { entry.label.remove(); return; }
    lastDelay = Math.max(lastDelay, p.delay);
    entry.label.style.left = `${p.left}px`;
    entry.label.style.top = `${p.top}px`;
    entry.label.style.setProperty('--flight-x', `${entry.x - p.left - entry.width / 2}px`);
    entry.label.style.setProperty('--flight-y', `${entry.y - p.top - entry.height / 2}px`);
    for (const node of [entry.label, entry.badge]) node.style.setProperty('--flight-delay', `${p.delay}ms`);
    entry.label.classList.add('is-flying');
    entry.badge.classList.add('replay-win-flight-source');
  });
  quad.dataset.flying = 'true';
  const cleanup = () => {
    clearTimeout(timer);
    entries.forEach(({ label, badge }) => {
      label.remove(); badge.classList.remove('replay-win-flight-source');
      badge.style.removeProperty('--flight-delay');
    });
    delete quad.dataset.flying;
    view.removeEventListener('resize', cleanup);
    active.delete(quad);
  };
  const timer = setTimeout(cleanup, lastDelay + 1300);
  active.set(quad, cleanup);
  view.addEventListener('resize', cleanup, { once: true });
}

/** Keep a manually inspected prize beside its badge, clear of the total and seal. */
export function positionBadgeReward(badge, center) {
  const quad = badge.parentElement;
  const reward = badge.querySelector('.replay-badge-reward-pop');
  if (!quad?.clientWidth || !reward) return;
  const bounds = quad.getBoundingClientRect();
  const sx = quad.clientWidth / bounds.width, sy = quad.clientHeight / bounds.height;
  const local = node => {
    const r = node.getBoundingClientRect();
    return { left: (r.left - bounds.left) * sx, top: (r.top - bounds.top) * sy, width: r.width * sx, height: r.height * sy };
  };
  reward.style.maxWidth = `${quad.clientWidth - 6}px`;
  const source = local(badge);
  const item = { x: source.left + source.width / 2, y: source.top + source.height / 2,
    width: reward.offsetWidth, height: reward.offsetHeight };
  const obstacles = [center, quad.querySelector('.replay-win-description')].filter(Boolean).map(local);
  const [position] = layoutWinFlights([item], { left: 3, top: 3, right: quad.clientWidth - 3, bottom: quad.clientHeight - 3 }, obstacles);
  if (!position) return;
  reward.style.left = `${position.left - source.left}px`;
  reward.style.top = `${position.top - source.top}px`;
  reward.style.bottom = 'auto';
  reward.style.setProperty('--replay-reward-base-x', '0%');
  reward.style.setProperty('--replay-reward-base-y', '0%');
  badge.dataset.rewardDirection = 'placed';
}
